python -c "import json,io,sys; 
f=open(r'C:\app\.gsa\runs\RUN-CLI-6a98817a\events.jsonl','r',encoding='utf-8');
out=open(r'C:\app\.tmp\prior_run_extract.txt','w',encoding='utf-8');
for line in f:
    try: e=json.loads(line)
    except: continue
    p=e.get('payload',{});
    et=e.get('event_type','');
    if et=='model_output':
        tc=p.get('tool_calls') or [];
        for c in tc:
            out.write('=== MODEL_TOOL_CALL %s %s\n'%(c.get('name'),json.dumps(c.get('arguments',{}))))
    elif et=='tool_completed':
        r=p.get('result') or p;
        s=json.dumps(r)
        out.write('--- RESULT (call %s, exit %s): %s\n'%(p.get('call_id'),p.get('exit_code'),s[:2500]))
out.close(); f.close(); print('done')"
